      const delta = st - w2.lastTop;                  // 的 D0 尾巴）；停止收口走 80ms 静默，不靠 delta=0
      w2.lastTop = st;
      fire('scroll', delta, 1);                       // ScrollState.Scroll=1（Idle=0/Fling=2）
      fire('didScroll', delta, 1);
