        position: (n, v) => { n.style.position = 'absolute'; n.style.left = Number((/** @type {any} */ (v)).x || 0) + 'px'; n.style.top = Number((/** @type {any} */ (v)).y || 0) + 'px'; },
        markAnchor: (n, v) => { n.dataset.markAnchor = JSON.stringify(v); },
